`, "",{"version":3,"sources":["webpack://./src/小手机/components/AvatarBadge.vue"],"names":[],"mappings":"AAqFA,+BACE,iBAAkB,CAClB,iBAAkB,CAClB,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,WAAY,CACZ,eAAgB,CAChB,aAAc,CACd,wBAAiB,CAAjB,gBAAiB,CACjB,cACF,CAEA,qCACE,uBACF,CAGA,0BACE,UAAW,CACX,WAAY,CACZ,cACF,CAEA,0BACE,UAAW,CACX,WAAY,CACZ,cACF,CAEA,0BACE,UAAW,CACX,WAAY,CACZ,cACF,CAEA,8BACE,aACF,CAEA,+BACE,UAAW,CACX,WAAY,CACZ,gBAAiB,CACjB,aAAc,CACd,iBACF,CAEA,+BACE,YACF,CAGA,6BACE,iBAAkB,CAClB,UAAW,CACX,SAAU,CACV,UAAW,CACX,WAAY,CACZ,kBAAmB,CACnB,0CAA4C,CAC5C,iBACF,CAEA,sCACE,SAAU,CACV,UAAW,CACX,QAAS,CACT,OACF,CAEA,sCACE,UAAW,CACX,WAAY,CACZ,UAAW,CACX,SACF,CAGA,8BACE,iBAAkB,CAClB,QAAS,CACT,UAAW,CACX,cAAe,CACf,WAAY,CACZ,aAAc,CACd,gCAAkC,CAClC,WAAY,CACZ,cAAe,CACf,eAAgB,CAChB,iBAAkB,CAClB,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,4CACF,CAEA,oCACE,cAAe,CACf,aACF","sourcesContent":["<template>\n  <div\n    class=\"avatar-badge\"\n    :class=\"[sizeClass, { 'has-image': !!avatarUrl }]\"\n    :style=\"avatarStyle\"\n    role=\"button\"\n    tabindex=\"0\"\n    title=\"点击更换头像\"\n    @click.stop=\"openAvatarPicker\"\n    @keydown.enter.prevent.stop=\"openAvatarPicker\"\n  >\n    <img v-if=\"avatarUrl\" class=\"avatar-image\" :src=\"avatarUrl\" :alt=\"props.name\" />\n    <span v-else class=\"avatar-text\">{{ initial }}</span>\n    <span v-if=\"online\" class=\"online-dot\"></span>\n    <span v-if=\"badge && badge > 0\" class=\"badge-count\" :class=\"{ large: badge > 99 }\">\n      {{ badge > 99 ? '99+' : badge }}\n    </span>\n    <input ref=\"avatarInputRef\" class=\"avatar-input\" type=\"file\" accept=\"image/*\" @change=\"onAvatarSelected\" @click.stop />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { usePhoneStore } from '../stores/phone-store';\n\ninterface Props {\n  /** 名字（取首字符） */\n  name: string;\n  /** 尺寸 */\n  size?: 'sm' | 'md' | 'lg';\n  /** 是否在线 */\n  online?: boolean;\n  /** 角标数字 */\n  badge?: number;\n  /** 自定义颜色 */\n  color?: string;\n}\n\nconst props = withDefaults(defineProps<Props>(), {\n  size: 'md',\n  online: false,\n  badge: 0,\n  color: '',\n});\n\nconst store = usePhoneStore();\nconst avatarInputRef = ref<HTMLInputElement | null>(null);\n\nconst AVATAR_COLORS = [\n  '#579bf0', '#50c9c3', '#f5a623', '#7ed321', '#e74c3c',\n  '#9b59b6', '#1db954', '#e91e63', '#ff5722', '#00bcd4',\n  '#8bc34a', '#ff9800', '#673ab7', '#795548', '#607d8b',\n];\n\nconst initial = computed(() => {\n  return props.name ? props.name.charAt(0) : '?';\n});\n\nconst bgColor = computed(() => {\n  if (props.color) return props.color;\n  const code = props.name.charCodeAt(0) || 0;\n  return AVATAR_COLORS[code % AVATAR_COLORS.length];\n});\n\nconst sizeClass = computed(() => `size-${props.size}`);\n\nconst avatarUrl = computed(() => store.getAvatar(props.name));\n\nconst avatarStyle = computed(() => ({\n  backgroundColor: bgColor.value,\n}));\n\nfunction openAvatarPicker() {\n  avatarInputRef.value?.click();\n}\n\nasync function onAvatarSelected(e: Event) {\n  const input = e.target as HTMLInputElement;\n  const file = input.files?.[0];\n  if (!file) return;\n  await store.setAvatar(props.name, file);\n  input.value = '';\n}\n</script>\n\n<style scoped>\n.avatar-badge {\n  position: relative;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: white;\n  font-weight: 600;\n  flex-shrink: 0;\n  user-select: none;\n  cursor: pointer;\n}\n\n.avatar-badge:hover {\n  filter: brightness(1.04);\n}\n\n/* 尺寸 */\n.size-sm {\n  width: 32px;\n  height: 32px;\n  font-size: 13px;\n}\n\n.size-md {\n  width: 44px;\n  height: 44px;\n  font-size: 17px;\n}\n\n.size-lg {\n  width: 56px;\n  height: 56px;\n  font-size: 22px;\n}\n\n.avatar-text {\n  line-height: 1;\n}\n\n.avatar-image {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n  border-radius: 50%;\n}\n\n.avatar-input {\n  display: none;\n}\n\n/* 在线指示 */\n.online-dot {\n  position: absolute;\n  bottom: 1px;\n  right: 1px;\n  width: 10px;\n  height: 10px;\n  background: #27ae60;\n  border: 2px solid var(--bg-primary, #0b0e14);\n  border-radius: 50%;\n}\n\n.size-sm .online-dot {\n  width: 8px;\n  height: 8px;\n  bottom: 0;\n  right: 0;\n}\n\n.size-lg .online-dot {\n  width: 12px;\n  height: 12px;\n  bottom: 2px;\n  right: 2px;\n}\n\n/* 角标 */\n.badge-count {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  min-width: 16px;\n  height: 16px;\n  padding: 0 4px;\n  background: var(--danger, #e74c3c);\n  color: white;\n  font-size: 10px;\n  font-weight: 700;\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1.5px solid var(--bg-primary, #0b0e14);\n}\n\n.badge-count.large {\n  min-width: 22px;\n  font-size: 9px;\n}\n</style>\n"],"sourceRoot":""}]);
