tring;\n  label: string;\n  badge?: number;\n}\n\ndefineProps<{\n  tabs: TabItem[];\n  activeTab: string;\n}>();\n\ndefineEmits<{\n  (e: 'tab-change', tabId: string): void;\n}>();\n</script>\n\n<style scoped>\n.tabbar {\n  display: flex;\n  align-items: stretch;\n  background: var(--bg-tabbar, rgba(12, 14, 20, 0.95));\n  backdrop-filter: blur(12px);\n  border-top: 1px solid var(--border-secondary, rgba(255, 255, 255, 0.06));\n  flex-shrink: 0;\n  padding: 6px 0 8px;\n}\n\n.tabbar-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 3px;\n  padding: 4px 0;\n  border: none;\n  background: transparent;\n  color: var(--text-muted, rgba(255, 255, 255, 0.35));\n  cursor: pointer;\n  transition: all 0.2s ease;\n  position: relative;\n}\n\n.tabbar-item:active {\n  transform: scale(0.95);\n}\n\n.tabbar-item.active {\n  color: var(--accent, #579bf0);\n}\n\n.tabbar-item:not(.active):hover {\n  color: var(--text-tertiary, rgba(255, 255, 255, 0.55));\n}\n\n.icon-container {\n  position: relative;\n  width: 26px;\n  height: 26px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.tab-icon {\n  width: 24px;\n  height: 24px;\n  transition: transform 0.2s ease;\n}\n\n.tabbar-item.active .tab-icon {\n  transform: scale(1.1);\n}\n\n.unread-dot {\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 8px;\n  height: 8px;\n  background: var(--danger, #e74c3c);\n  border-radius: 50%;\n  border: 2px solid var(--bg-tabbar);\n  animation: pulse 2s ease-in-out infinite;\n}\n\n@keyframes pulse {\n  0%, 100% { transform: scale(1); opacity: 1; }\n  50% { transform: scale(1.1); opacity: 0.8; }\n}\n\n.tab-label {\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.3px;\n}\n</style>\n"],"sourceRoot":""}]);
